-- Schema-only PostgreSQL baseline translated from the supplied MySQL dump.
-- INSERT statements and all application records from the dump are intentionally excluded.
-- This script also reconciles the already-inspected empty Supabase schema without dropping objects.

CREATE TABLE IF NOT EXISTS public."announcements" (
    "announcement_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(200) NOT NULL,
    "body" text NOT NULL,
    "author_id" integer,
    "is_published" smallint NOT NULL DEFAULT 1,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("announcement_id")
);

CREATE TABLE IF NOT EXISTS public."bookings" (
    "booking_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "full_name" varchar(150) NOT NULL,
    "email" varchar(150) NOT NULL,
    "phone" varchar(40),
    "room_id" integer,
    "reservation_type" text NOT NULL DEFAULT 'capacity_based' CHECK ("reservation_type" IN ('capacity_based', 'entire_room')),
    "occupant_count" bigint NOT NULL DEFAULT 1 CHECK ("occupant_count" >= 0 AND "occupant_count" <= 4294967295),
    "move_in_date" date,
    "check_out_date" date,
    "length_of_stay_months" numeric(6,2) NOT NULL DEFAULT 1.00,
    "payment_plan" text NOT NULL DEFAULT 'Pay Monthly' CHECK ("payment_plan" IN ('Pay in Full', 'Pay Monthly', 'Pay One Month Rent')),
    "total_rent" numeric(10,2) NOT NULL DEFAULT 0.00,
    "checked_in_at" timestamp without time zone,
    "checked_out_at" timestamp without time zone,
    "notes" text,
    "status" text NOT NULL DEFAULT 'Pending' CHECK ("status" IN ('Pending', 'Pending Verification', 'Confirmed', 'Checked In', 'Active', 'Checked Out', 'Cancelled', 'Rejected', 'Expired')),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone,
    "payment_expires_at" timestamp without time zone,
    "payment_reminder_sent_at" timestamp without time zone,
    PRIMARY KEY ("booking_id")
);

CREATE TABLE IF NOT EXISTS public."booking_initial_payment_requests" (
    "booking_id" integer NOT NULL,
    "method" text NOT NULL CHECK ("method" IN ('GCash', 'PayPal')),
    "status" text NOT NULL DEFAULT 'Checkout' CHECK ("status" IN ('Checkout', 'Submitted', 'Confirmed', 'Rejected')),
    "amount" numeric(10,2) NOT NULL,
    "reference_number" varchar(120),
    "screenshot_path" varchar(255),
    "paypal_order_id" varchar(40),
    "paypal_order_history" text,
    "paypal_capture_id" varchar(40),
    "paypal_capture_request_id" char(32),
    "paypal_capture_attempts" bigint NOT NULL DEFAULT 0 CHECK ("paypal_capture_attempts" >= 0 AND "paypal_capture_attempts" <= 4294967295),
    "paypal_refund_id" varchar(40),
    "paypal_refund_request_id" char(32),
    "paypal_refund_attempts" bigint NOT NULL DEFAULT 0 CHECK ("paypal_refund_attempts" >= 0 AND "paypal_refund_attempts" <= 4294967295),
    "paypal_retry_at" timestamp without time zone,
    "paypal_processing_lease_until" timestamp without time zone,
    "paypal_last_error" text,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone,
    PRIMARY KEY ("booking_id")
);

CREATE TABLE IF NOT EXISTS public."booking_room_holds" (
    "hold_id" bigint GENERATED BY DEFAULT AS IDENTITY CHECK ("hold_id" >= 0 AND "hold_id" <= 9223372036854775807),
    "user_id" integer NOT NULL,
    "email" varchar(255) NOT NULL,
    "room_id" integer NOT NULL,
    "move_in_date" date,
    "check_out_date" date,
    "reservation_type" text NOT NULL DEFAULT 'capacity_based' CHECK ("reservation_type" IN ('capacity_based', 'entire_room')),
    "occupant_count" bigint NOT NULL DEFAULT 1 CHECK ("occupant_count" >= 0 AND "occupant_count" <= 4294967295),
    "expires_at" timestamp without time zone NOT NULL,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone,
    PRIMARY KEY ("hold_id")
);

CREATE TABLE IF NOT EXISTS public."cancellation_requests" (
    "cancellation_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" integer NOT NULL,
    "room_id" integer NOT NULL,
    "monthly_rent" numeric(10,2) NOT NULL,
    "move_in_date" date NOT NULL,
    "cancellation_date" date NOT NULL,
    "daily_rate" numeric(10,2) NOT NULL,
    "days_consumed" integer NOT NULL,
    "amount_used" numeric(10,2) NOT NULL,
    "refund_amount" numeric(10,2) NOT NULL,
    "status" text NOT NULL DEFAULT 'Pending' CHECK ("status" IN ('Pending', 'Approved', 'Rejected', 'Withdrawn', 'Expired')),
    "cancellation_expires_at" timestamp without time zone NOT NULL,
    "rejection_reason" text,
    "requested_by" integer,
    "acted_by" integer,
    "acted_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "gcash_account_name" varchar(120) NOT NULL DEFAULT '',
    "gcash_number" varchar(30) NOT NULL DEFAULT '',
    "transaction_reference" varchar(120),
    "screenshot_path" varchar(255),
    PRIMARY KEY ("cancellation_id")
);

CREATE TABLE IF NOT EXISTS public."chatbot_faqs" (
    "faq_id" bigint GENERATED BY DEFAULT AS IDENTITY CHECK ("faq_id" >= 0 AND "faq_id" <= 4294967295),
    "category" varchar(32) NOT NULL,
    "question" varchar(255) NOT NULL,
    "answer" text NOT NULL,
    "is_active" smallint NOT NULL DEFAULT 1,
    "is_suggested" smallint NOT NULL DEFAULT 0,
    "sort_order" smallint NOT NULL DEFAULT 0 CHECK ("sort_order" >= 0 AND "sort_order" <= 255),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("faq_id")
);

CREATE TABLE IF NOT EXISTS public."chatbot_suggested_questions" (
    "suggested_question_id" bigint GENERATED BY DEFAULT AS IDENTITY CHECK ("suggested_question_id" >= 0 AND "suggested_question_id" <= 4294967295),
    "question" varchar(255) NOT NULL,
    "is_active" smallint NOT NULL DEFAULT 1,
    "sort_order" integer NOT NULL DEFAULT 0,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("suggested_question_id")
);

CREATE TABLE IF NOT EXISTS public."chat_messages" (
    "message_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "from_user_id" integer NOT NULL,
    "to_user_id" integer NOT NULL,
    "body" text NOT NULL,
    "is_read" smallint NOT NULL DEFAULT 0,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "guest_name" varchar(255),
    "guest_email" varchar(255),
    "image_path" varchar(255),
    "is_unsent" smallint NOT NULL DEFAULT 0,
    PRIMARY KEY ("message_id")
);

CREATE TABLE IF NOT EXISTS public."chat_message_hidden" (
    "message_id" integer NOT NULL,
    "user_id" integer NOT NULL,
    "hidden_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("message_id", "user_id")
);

CREATE TABLE IF NOT EXISTS public."chat_message_images" (
    "image_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "message_id" integer NOT NULL,
    "image_path" varchar(255) NOT NULL,
    "sort_order" smallint NOT NULL DEFAULT 0 CHECK ("sort_order" >= 0 AND "sort_order" <= 255),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("image_id")
);

CREATE TABLE IF NOT EXISTS public."complaints" (
    "complaint_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" integer NOT NULL,
    "title" varchar(180) NOT NULL,
    "description" text,
    "category" varchar(80),
    "is_urgent" smallint NOT NULL DEFAULT 0,
    "photo_path" varchar(255),
    "status" text NOT NULL DEFAULT 'Submitted' CHECK ("status" IN ('Submitted', 'Acknowledged', 'In Progress', 'Resolved', 'Cancelled')),
    "admin_reply" text,
    "replied_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone,
    PRIMARY KEY ("complaint_id")
);

CREATE TABLE IF NOT EXISTS public."complaint_status_history" (
    "history_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "complaint_id" integer NOT NULL,
    "status" text NOT NULL CHECK ("status" IN ('Submitted', 'Acknowledged', 'In Progress', 'Resolved', 'Cancelled')),
    "changed_by" integer,
    "changed_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("history_id")
);

CREATE TABLE IF NOT EXISTS public."contact_messages" (
    "message_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(150) NOT NULL,
    "email" varchar(150) NOT NULL,
    "subject" varchar(200),
    "message" text NOT NULL,
    "is_read" smallint NOT NULL DEFAULT 0,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("message_id")
);

CREATE TABLE IF NOT EXISTS public."full_payment_requests" (
    "request_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" integer NOT NULL,
    "user_id" integer NOT NULL,
    "total_amount" numeric(10,2) NOT NULL,
    "status" text NOT NULL DEFAULT 'Requested' CHECK ("status" IN ('Requested', 'Approved', 'Rejected', 'Submitted', 'Confirmed', 'Cancelled')),
    "qr_path" varchar(255),
    "admin_note" text,
    "reference_number" varchar(120),
    "screenshot_path" varchar(255),
    "approved_by" integer,
    "approved_at" timestamp without time zone,
    "submitted_at" timestamp without time zone,
    "confirmed_by" integer,
    "confirmed_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("request_id")
);

CREATE TABLE IF NOT EXISTS public."full_payment_request_items" (
    "request_id" integer NOT NULL,
    "payment_id" integer NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    PRIMARY KEY ("request_id", "payment_id")
);

CREATE TABLE IF NOT EXISTS public."gcash_qr_codes" (
    "qr_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "filename" varchar(255) NOT NULL,
    "amount" numeric(10,2),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("qr_id")
);

CREATE TABLE IF NOT EXISTS public."gcash_transaction_references" (
    "reference_number" varchar(120) NOT NULL,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("reference_number")
);

CREATE TABLE IF NOT EXISTS public."maintenance_requests" (
    "request_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" integer NOT NULL,
    "title" varchar(180) NOT NULL,
    "category" varchar(80) NOT NULL DEFAULT 'General',
    "photo_path" varchar(255),
    "description" text,
    "priority" text NOT NULL DEFAULT 'Medium' CHECK ("priority" IN ('Low', 'Medium', 'High', 'Urgent')),
    "status" text NOT NULL DEFAULT 'Submitted' CHECK ("status" IN ('Submitted', 'Acknowledged', 'In Progress', 'Resolved', 'Cancelled')),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone,
    PRIMARY KEY ("request_id")
);

CREATE TABLE IF NOT EXISTS public."maintenance_status_history" (
    "history_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "request_id" integer NOT NULL,
    "status" text NOT NULL CHECK ("status" IN ('Submitted', 'Acknowledged', 'In Progress', 'Resolved', 'Cancelled')),
    "changed_by" integer,
    "changed_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("history_id")
);

CREATE TABLE IF NOT EXISTS public."notifications" (
    "notification_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "user_id" integer NOT NULL,
    "title" varchar(200) NOT NULL,
    "message" text,
    "type" varchar(60),
    "is_read" smallint NOT NULL DEFAULT 0,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("notification_id")
);

CREATE TABLE IF NOT EXISTS public."payments" (
    "payment_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "booking_id" integer,
    "tenant_id" integer,
    "amount" numeric(10,2) NOT NULL DEFAULT 0.00,
    "due_date" date,
    "status" text NOT NULL DEFAULT 'Pending' CHECK ("status" IN ('Pending', 'Submitted', 'Confirmed', 'Paid', 'Rejected', 'Overdue', 'Cancelled')),
    "description" varchar(255),
    "payment_type" varchar(80),
    "method" varchar(80),
    "gateway" varchar(20) NOT NULL DEFAULT 'paypal',
    "reference_number" varchar(120),
    "paypal_order_id" varchar(40),
    "paypal_capture_id" varchar(40),
    "submitted_at" timestamp without time zone,
    "confirmation_date" timestamp without time zone,
    "confirmed_by" integer,
    "paid_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("payment_id")
);

CREATE TABLE IF NOT EXISTS public."payment_proofs" (
    "payment_id" integer NOT NULL,
    "screenshot_path" varchar(255) NOT NULL,
    "uploaded_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("payment_id")
);

CREATE TABLE IF NOT EXISTS public."ratings" (
    "rating_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" integer NOT NULL,
    "category" text NOT NULL DEFAULT 'Overall Satisfaction' CHECK ("category" IN ('Facilities', 'Services', 'Overall Satisfaction')),
    "stars" numeric(2,1) NOT NULL DEFAULT 5.0,
    "comment" text,
    "moderation_status" text NOT NULL DEFAULT 'Pending' CHECK ("moderation_status" IN ('Pending', 'Approved', 'Hidden')),
    "admin_reply" text,
    "replied_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("rating_id")
);

CREATE TABLE IF NOT EXISTS public."refund_requests" (
    "refund_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "payment_id" integer NOT NULL,
    "user_id" integer NOT NULL,
    "refund_amount" numeric(10,2) NOT NULL,
    "gcash_account_name" varchar(120) NOT NULL DEFAULT '',
    "gcash_number" varchar(30) NOT NULL DEFAULT '',
    "transaction_reference" varchar(120),
    "screenshot_path" varchar(255),
    "transfer_reference" varchar(120),
    "transfer_screenshot_path" varchar(255),
    "reason" text,
    "status" text NOT NULL DEFAULT 'Pending' CHECK ("status" IN ('Pending', 'Approved', 'Rejected')),
    "admin_note" text,
    "acted_by" integer,
    "acted_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("refund_id")
);

CREATE TABLE IF NOT EXISTS public."rooms" (
    "room_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "room_number" varchar(40) NOT NULL,
    "room_type" varchar(80) NOT NULL,
    "capacity" integer NOT NULL DEFAULT 1,
    "monthly_rent" numeric(10,2) NOT NULL DEFAULT 0.00,
    "status" text NOT NULL DEFAULT 'Available' CHECK ("status" IN ('Available', 'Reserving', 'Occupied', 'Reserved', 'Maintenance')),
    "description" text,
    "image" varchar(255),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("room_id")
);

CREATE TABLE IF NOT EXISTS public."room_change_requests" (
    "request_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" integer NOT NULL,
    "requested_room_id" integer,
    "reason" text,
    "status" text NOT NULL DEFAULT 'Pending' CHECK ("status" IN ('Pending', 'Approved', 'Rejected')),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("request_id")
);

CREATE TABLE IF NOT EXISTS public."room_images" (
    "image_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "room_id" integer NOT NULL,
    "filename" varchar(255) NOT NULL,
    "caption" varchar(255) NOT NULL DEFAULT '',
    "sort_order" integer NOT NULL DEFAULT 0,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("image_id")
);

CREATE TABLE IF NOT EXISTS public."sms_delivery_log" (
    "event_key" varchar(190) NOT NULL,
    "recipient_phone" varchar(40) NOT NULL,
    "status" text NOT NULL DEFAULT 'sending' CHECK ("status" IN ('sending', 'sent', 'failed')),
    "attempted_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "sent_at" timestamp without time zone,
    "last_error" varchar(500),
    PRIMARY KEY ("event_key", "recipient_phone")
);

CREATE TABLE IF NOT EXISTS public."stay_change_requests" (
    "request_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "booking_id" integer NOT NULL,
    "request_type" text NOT NULL CHECK ("request_type" IN ('Extension', 'Early Checkout')),
    "original_check_out_date" date NOT NULL,
    "requested_check_out_date" date NOT NULL,
    "status" text NOT NULL DEFAULT 'Pending' CHECK ("status" IN ('Pending', 'Approved', 'Rejected')),
    "applicable_charge" numeric(10,2) NOT NULL DEFAULT 0.00,
    "refund_amount" numeric(10,2) NOT NULL DEFAULT 0.00,
    "requested_by" integer,
    "acted_by" integer,
    "acted_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("request_id")
);

CREATE TABLE IF NOT EXISTS public."system_logs" (
    "log_id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "actor_id" integer,
    "category" varchar(40) NOT NULL DEFAULT 'general',
    "action" varchar(80) NOT NULL,
    "level" text NOT NULL DEFAULT 'info' CHECK ("level" IN ('info', 'warning', 'error', 'security')),
    "message" text,
    "ip_address" varchar(64),
    "user_agent" varchar(255),
    "request_path" varchar(255),
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("log_id")
);

CREATE TABLE IF NOT EXISTS public."system_settings" (
    "setting_key" varchar(100) NOT NULL,
    "setting_value" text,
    PRIMARY KEY ("setting_key")
);

CREATE TABLE IF NOT EXISTS public."tenants" (
    "tenant_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "user_id" integer,
    "room_id" integer,
    "reservation_type" text NOT NULL DEFAULT 'capacity_based' CHECK ("reservation_type" IN ('capacity_based', 'entire_room')),
    "occupant_count" bigint NOT NULL DEFAULT 1 CHECK ("occupant_count" >= 0 AND "occupant_count" <= 4294967295),
    "full_name" varchar(150) NOT NULL,
    "phone" varchar(40),
    "email" varchar(150),
    "move_in_date" date,
    "move_out_date" date,
    "is_active" smallint NOT NULL DEFAULT 1,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("tenant_id")
);

CREATE TABLE IF NOT EXISTS public."users" (
    "user_id" integer GENERATED BY DEFAULT AS IDENTITY,
    "full_name" varchar(150) NOT NULL,
    "username" varchar(80) NOT NULL,
    "email" varchar(150) NOT NULL,
    "phone" varchar(40),
    "address" varchar(255),
    "age" smallint CHECK ("age" >= 0 AND "age" <= 255),
    "birthday" date,
    "emergency_contact_name" varchar(150),
    "emergency_contact_phone" varchar(40),
    "password" varchar(255) NOT NULL,
    "profile_picture" varchar(255),
    "user_type" text NOT NULL DEFAULT 'Tenant' CHECK ("user_type" IN ('Admin', 'Tenant', 'Guest')),
    "is_active" smallint NOT NULL DEFAULT 1,
    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("user_id")
);

ALTER TABLE public."cancellation_requests"
