DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public."announcements"'::regclass
      AND conname = 'announcements_ibfk_1'
  ) THEN
    ALTER TABLE public."announcements" ADD CONSTRAINT "announcements_ibfk_1" FOREIGN KEY ("author_id") REFERENCES public."users" ("user_id") ON DELETE SET NULL;
  END IF;
END;
$$;

