CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER "trg_chatbot_faqs_updated_at" BEFORE UPDATE ON public."chatbot_faqs" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE TRIGGER "trg_bookings_updated_at" BEFORE UPDATE ON public."bookings" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE TRIGGER "trg_booking_initial_payment_requests_updated_at" BEFORE UPDATE ON public."booking_initial_payment_requests" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE TRIGGER "trg_complaints_updated_at" BEFORE UPDATE ON public."complaints" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE TRIGGER "trg_maintenance_requests_updated_at" BEFORE UPDATE ON public."maintenance_requests" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE TRIGGER "trg_full_payment_requests_updated_at" BEFORE UPDATE ON public."full_payment_requests" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
